macro_rules! deps {
    () => {
        Span!();
    };
}

macro_rules! Ident {
    () => {
        deps!();
        # [doc = " A word of Rust code, which may be a keyword or legal variable name."] # [doc = ""] # [doc = " An identifier consists of at least one Unicode code point, the first of"] # [doc = " which has the XID_Start property and the rest of which have the XID_Continue"] # [doc = " property."] # [doc = ""] # [doc = " - The empty string is not an identifier. Use `Option<Ident>`."] # [doc = " - A lifetime is not an identifier. Use `syn::Lifetime` instead."] # [doc = ""] # [doc = " An identifier constructed with `Ident::new` is permitted to be a Rust"] # [doc = " keyword, though parsing one through its [`Parse`] implementation rejects"] # [doc = " Rust keywords. Use `input.call(Ident::parse_any)` when parsing to match the"] # [doc = " behaviour of `Ident::new`."] # [doc = ""] # [doc = " [`Parse`]: https://docs.rs/syn/2.0/syn/parse/trait.Parse.html"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " A new ident can be created from a string using the `Ident::new` function."] # [doc = " A span must be provided explicitly which governs the name resolution"] # [doc = " behavior of the resulting identifier."] # [doc = ""] # [doc = " ```"] # [doc = " use proc_macro2::{Ident, Span};"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     let call_ident = Ident::new(\"calligraphy\", Span::call_site());"] # [doc = ""] # [doc = "     println!(\"{}\", call_ident);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " An ident can be interpolated into a token stream using the `quote!` macro."] # [doc = ""] # [doc = " ```"] # [doc = " use proc_macro2::{Ident, Span};"] # [doc = " use quote::quote;"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     let ident = Ident::new(\"demo\", Span::call_site());"] # [doc = ""] # [doc = "     // Create a variable binding whose name is this ident."] # [doc = "     let expanded = quote! { let #ident = 10; };"] # [doc = ""] # [doc = "     // Create a variable binding with a slightly different name."] # [doc = "     let temp_ident = Ident::new(&format!(\"new_{}\", ident), Span::call_site());"] # [doc = "     let expanded = quote! { let #temp_ident = 10; };"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " A string representation of the ident is available through the `to_string()`"] # [doc = " method."] # [doc = ""] # [doc = " ```"] # [doc = " # use proc_macro2::{Ident, Span};"] # [doc = " #"] # [doc = " # let ident = Ident::new(\"another_identifier\", Span::call_site());"] # [doc = " #"] # [doc = " // Examine the ident as a string."] # [doc = " let ident_string = ident.to_string();"] # [doc = " if ident_string.len() > 60 {"] # [doc = "     println!(\"Very long identifier: {}\", ident_string)"] # [doc = " }"] # [doc = " ```"] # [derive (Clone)] pub struct Ident { inner : imp :: Ident , _marker : ProcMacroAutoTraits , }
    };
}

Ident!()